#!/bin/bash
# ═══════════════════════════════════════════════════════════════════════
#  SmartVision — Installateur autonome
#  Raspberry Pi 4 / Pi 5 · Raspberry Pi OS Lite 64-bit
#  © Lucas BOUVERET — Tous droits réservés
#  Usage : chmod +x install_standalone.sh && sudo ./install_standalone.sh
# ═══════════════════════════════════════════════════════════════════════
SMARTVISION_VERSION="3.7.0"
BUILD_DATE="2026-06"
set -e

RED='\033[0;31m'; GREEN='\033[0;32m'; YELLOW='\033[1;33m'
BLUE='\033[0;34m'; CYAN='\033[0;36m'; BOLD='\033[1m'; NC='\033[0m'
ok()   { echo -e "${GREEN}  ✔  $*${NC}"; }
info() { echo -e "${CYAN}  →  $*${NC}"; }
warn() { echo -e "${YELLOW}  ⚠  $*${NC}"; }
fail() { echo -e "${RED}  ✖  $*${NC}\n"; echo -e "${YELLOW}  Détails de l'erreur : ${LOGFILE}${NC}"; exit 1; }
step() { echo -e "\n${BOLD}${BLUE}[$1] $2${NC}"; }

# Fichier log pour toute la sortie verbeuse (apt, pip…)
LOGFILE="/tmp/smartvision-install.log"
: > "$LOGFILE"

# run "message" commande…  → affiche le message, exécute en silence,
# et n'affiche les détails QUE si la commande échoue
run() {
    local msg="$1"; shift
    printf "${CYAN}  →  %s...${NC}" "$msg"
    if "$@" >> "$LOGFILE" 2>&1; then
        printf "\r${GREEN}  ✔  %s      ${NC}\n" "$msg"
    else
        printf "\r${RED}  ✖  %s${NC}\n" "$msg"
        echo -e "${YELLOW}  ── Dernières lignes du log : ────────────────${NC}"
        tail -n 15 "$LOGFILE" | sed 's/^/     /'
        echo -e "${YELLOW}  ─────────────────────────────────────────────${NC}"
        echo -e "${YELLOW}  Log complet : ${LOGFILE}${NC}"
        exit 1
    fi
}

[ "$EUID" -ne 0 ] && fail "Lancez avec sudo : sudo ./install_standalone.sh"

# Nettoyage complet de l'écran (efface aussi l'historique de défilement)
clear 2>/dev/null || true
printf '\033[3J\033[H\033[2J'   # efface scrollback + repositionne + efface écran

echo -e "${BOLD}${CYAN}"
echo "  ╔══════════════════════════════════════════════╗"
echo "  ║            SmartVision — Installation         ║"
echo "  ║        Raspberry Pi 4 / 5 · Dual Screen      ║"
printf "  ║                Version %-6s                ║\n" "${SMARTVISION_VERSION}"
echo "  ║      © Lucas BOUVERET — Tous droits réservés  ║"
echo "  ╚══════════════════════════════════════════════╝${NC}\n"

REAL_USER=${SUDO_USER:-$(logname 2>/dev/null || echo pi)}
INSTALL_DIR="/home/${REAL_USER}/videoplayer"
info "Version     : ${SMARTVISION_VERSION} (${BUILD_DATE})"
info "Utilisateur : ${REAL_USER}"
info "Répertoire  : ${INSTALL_DIR}"
info "Journal     : ${LOGFILE}"

step "1/6" "Mise à jour et dépendances système"
run "Mise à jour des paquets (apt update)" apt-get update -qq
run "Installation mpv, weston, ffmpeg, python" apt-get install -y -qq \
    mpv weston python3-pip python3-venv \
    libegl-mesa0 libgles2 libwayland-egl1 mesa-utils socat ffmpeg \
    fonts-comic-neue fonts-dejavu-core fonts-roboto
command -v mpv     >/dev/null || fail "MPV non installé"
command -v weston  >/dev/null || fail "Weston non installé"
command -v python3 >/dev/null || fail "Python3 non installé"
ok "mpv / weston / python3 installés"

step "2/6" "Création des répertoires"
mkdir -p "${INSTALL_DIR}/static" "${INSTALL_DIR}/uploads" "${INSTALL_DIR}/carte"
chown -R "${REAL_USER}:${REAL_USER}" "${INSTALL_DIR}"
ok "Répertoires prêts (uploads/ et DB conservés)"

step "3/6" "Déploiement des fichiers"
info "app.py..."
echo "" | base64 -d > "${INSTALL_DIR}/app.py"
info "static/index.html..."
echo "" | base64 -d > "${INSTALL_DIR}/static/index.html"
info "carte.py..."
echo "" | base64 -d > "${INSTALL_DIR}/carte.py"
chown -R "${REAL_USER}:${REAL_USER}" "${INSTALL_DIR}"
ok "Fichiers déployés"

step "4/6" "Environnement Python"
# Recréer le venv s'il est absent OU corrompu (python injouable)
if [ ! -x "${INSTALL_DIR}/venv/bin/python" ] || \
   ! "${INSTALL_DIR}/venv/bin/python" -c "import sys" >/dev/null 2>&1; then
    [ -d "${INSTALL_DIR}/venv" ] && { info "Venv absent ou corrompu — recréation"; rm -rf "${INSTALL_DIR}/venv"; }
    run "Création de l'environnement Python" \
        sudo -u "${REAL_USER}" python3 -m venv "${INSTALL_DIR}/venv"
fi
run "Mise à jour de pip" \
    sudo -u "${REAL_USER}" "${INSTALL_DIR}/venv/bin/pip" install --quiet --upgrade pip
run "Installation fastapi, uvicorn, python-multipart, pillow" \
    sudo -u "${REAL_USER}" "${INSTALL_DIR}/venv/bin/pip" install --quiet \
    fastapi "uvicorn[standard]" python-multipart zeroconf pillow
ok "Venv prêt : $(${INSTALL_DIR}/venv/bin/python --version 2>&1)"

step "5/6" "Services systemd"
info "Configuration weston (masquage du panneau)..."
cat > /etc/weston-kiosk.ini << 'WINI'
[core]
# Démarrer même sans écran branché (les écrans sont pris en charge à chaud)
require-outputs=none

[shell]
panel-position=none
locking=false
animation=none
startup-animation=none
WINI
ok "weston-kiosk.ini créé (panneau masqué)"

info "Lanceur weston..."
# Choisit la carte graphique qui pilote les prises HDMI : son numéro (card0 /
# card1) peut changer d'un démarrage à l'autre selon l'ordre de chargement des
# pilotes. Attend qu'elle soit prête au lieu d'un délai fixe.
cat > /usr/local/sbin/sv-weston << 'SVWST'
#!/bin/bash
CARD=""
for i in $(seq 1 60); do
    for c in /sys/class/drm/card[0-9] /sys/class/drm/card[0-9][0-9]; do
        [ -e "$c" ] || continue
        n=$(basename "$c")
        if ls -d /sys/class/drm/"$n"-HDMI-* >/dev/null 2>&1; then CARD="$n"; break 2; fi
    done
    sleep 0.5
done
[ -n "$CARD" ] || { echo "Aucune carte graphique HDMI trouvée"; exit 1; }
echo "Carte graphique HDMI : $CARD"
rm -f /tmp/wayland-weston /tmp/wayland-weston.lock
exec /usr/bin/weston --backend=drm-backend.so --socket=wayland-weston --idle-time=0 \
     --config=/etc/weston-kiosk.ini --drm-device="$CARD"
SVWST
chmod 755 /usr/local/sbin/sv-weston

info "Service weston..."
# Terminal virtuel 7, séparé de la console de connexion (tty1) : avant 3.7.0
# les deux se partageaient tty1 et, selon l'ordre de démarrage, les écrans
# restaient sur la page de connexion.
cat > /etc/systemd/system/weston.service << 'WSVC'
[Unit]
Description=Weston Wayland Compositor (SmartVision)
After=systemd-logind.service local-fs.target systemd-user-sessions.service getty@tty1.service
Wants=systemd-logind.service
Conflicts=getty@tty7.service
StartLimitIntervalSec=0

[Service]
Type=simple
User=root
Environment=XDG_RUNTIME_DIR=/tmp
Environment=WAYLAND_DISPLAY=wayland-weston
ExecStartPre=-/usr/bin/chvt 7
ExecStart=/usr/local/sbin/sv-weston
ExecStartPost=/bin/sh -c 'for i in $$(seq 1 40); do [ -S /tmp/wayland-weston ] && break; sleep 0.25; done; chmod 777 /tmp/wayland-weston; chmod 666 /tmp/wayland-weston.lock; true'
Restart=always
RestartSec=3
TimeoutStartSec=60

[Install]
WantedBy=multi-user.target
WSVC

info "Service videoplayer..."
PYBIN="${INSTALL_DIR}/venv/bin/python"
cat > /etc/systemd/system/videoplayer.service << VSVC
[Unit]
Description=SmartVision — Diffusion vidéo 2 écrans
After=network.target weston.service
Wants=weston.service
StartLimitIntervalSec=0

[Service]
Type=simple
User=${REAL_USER}
WorkingDirectory=${INSTALL_DIR}
ExecStart=${PYBIN} app.py
Restart=always
RestartSec=10
MemoryMax=800M
MemoryHigh=600M
Environment=PYTHONUNBUFFERED=1
Environment=XDG_RUNTIME_DIR=/tmp
Environment=WAYLAND_DISPLAY=wayland-weston
SupplementaryGroups=video render

[Install]
WantedBy=multi-user.target
VSVC

usermod -aG video,render "${REAL_USER}" 2>/dev/null || true

# Script de mise à jour appartenant à root : l'interface ne choisit que le
# canal (stable|beta), jamais l'URL ni le fichier exécuté.
# (Avant 3.2.1 : /tmp/sv_update.sh exécuté en root → faille, /tmp étant
#  accessible en écriture à tous.)
cat > /usr/local/sbin/sv-update << 'SVUPD'
#!/bin/bash
# SmartVision — mise à jour (lancé en root via sudo par videoplayer.service)
set -euo pipefail
case "${1:-}" in
    stable) BASE="https://raw.githubusercontent.com/Kalslow/Smartvision/main" ;;
    beta)   BASE="https://raw.githubusercontent.com/Kalslow/SVBETA/main" ;;
    *) echo "Usage : sv-update stable|beta" >&2; exit 2 ;;
esac
WORKDIR=$(mktemp -d /root/sv-update.XXXXXX)
trap 'rm -rf "$WORKDIR"' EXIT
wget -q "${BASE}/install_standalone.sh" -O "${WORKDIR}/install.sh"
sed -i 's/\r//' "${WORKDIR}/install.sh"
head -1 "${WORKDIR}/install.sh" | grep -q '^#!/bin/bash' \
    || { echo "Installateur invalide" >&2; exit 1; }
bash "${WORKDIR}/install.sh"
SVUPD
chown root:root /usr/local/sbin/sv-update
chmod 755 /usr/local/sbin/sv-update

# Actions matériel déclenchées par l'interface et la surveillance automatique
cat > /usr/local/sbin/sv-hw << 'SVHW'
#!/bin/bash
# SmartVision — actions matériel (lancé en root via sudo par videoplayer.service)
set -euo pipefail
CMDLINE=/boot/firmware/cmdline.txt
[ -f "$CMDLINE" ] || CMDLINE=/boot/cmdline.txt
FORCE="video=HDMI-A-1:1920x1080@60D video=HDMI-A-2:1920x1080@60D"
case "${1:-}" in
    focus)           chvt 7 ;;
    restart-display) systemctl restart weston ;;
    force-hdmi)
        case "${2:-}" in on|off) ;; *) echo "on|off" >&2; exit 2 ;; esac
        cp "$CMDLINE" "$CMDLINE.sv-bak"
        sed -i -E '1 s/ ?video=HDMI-A-[12]:[^ ]*//g' "$CMDLINE"
        [ "$2" = on ] && sed -i -E "1 s/\$/ $FORCE/" "$CMDLINE"
        grep -q 'root=' "$CMDLINE" || { cp "$CMDLINE.sv-bak" "$CMDLINE"; exit 1; }
        ;;
    *) echo "Usage : sv-hw focus|restart-display|force-hdmi on|off" >&2; exit 2 ;;
esac
SVHW
chown root:root /usr/local/sbin/sv-hw
chmod 755 /usr/local/sbin/sv-hw
rm -f /tmp/sv_update.sh

# Autoriser reboot et mise à jour sans mot de passe (boutons dans l'interface)
cat > /etc/sudoers.d/videoplayer-reboot << SUDOERS
${REAL_USER} ALL=(root) NOPASSWD: /sbin/reboot, /usr/sbin/reboot
${REAL_USER} ALL=(root) NOPASSWD: /usr/local/sbin/sv-update stable, /usr/local/sbin/sv-update beta
${REAL_USER} ALL=(root) NOPASSWD: /usr/local/sbin/sv-hw focus, /usr/local/sbin/sv-hw restart-display, /usr/local/sbin/sv-hw force-hdmi on, /usr/local/sbin/sv-hw force-hdmi off
SUDOERS
chmod 440 /etc/sudoers.d/videoplayer-reboot
visudo -cf /etc/sudoers.d/videoplayer-reboot >/dev/null \
    || { rm -f /etc/sudoers.d/videoplayer-reboot; fail "Règle sudoers invalide"; }
ok "Règle sudoers (reboot + mise à jour) ajoutée"

systemctl daemon-reload
systemctl enable weston videoplayer
ok "weston      : $(systemctl is-enabled weston 2>/dev/null)"
ok "videoplayer : $(systemctl is-enabled videoplayer 2>/dev/null)"

step "6/6" "Configuration GPU et démarrage"

PI_MODEL=$(tr -d '\0' < /proc/device-tree/model 2>/dev/null || echo "")
info "Modèle      : ${PI_MODEL:-inconnu}"
IS_PI5=false
case "$PI_MODEL" in
    *"Raspberry Pi 5"*|*"Raspberry Pi 500"*|*"Compute Module 5"*) IS_PI5=true ;;
esac

REBOOT_NEEDED=false
if [ "$IS_PI5" = true ]; then
    ok "Pi 5 : gpu_mem inutile (mémoire GPU gérée dynamiquement)"
else
# ── Mémoire GPU : 256 Mo (nécessaire pour dual-screen 1080p sur Pi 4) ──
CONFIG_FILE="/boot/firmware/config.txt"
# Compatibilité ancienne version RPi OS
[ ! -f "$CONFIG_FILE" ] && CONFIG_FILE="/boot/config.txt"

if grep -q "^gpu_mem=" "$CONFIG_FILE" 2>/dev/null; then
    # Mettre à jour la valeur existante
    sed -i "s/^gpu_mem=.*/gpu_mem=256/" "$CONFIG_FILE"
    ok "gpu_mem mis à jour → 256 Mo dans $CONFIG_FILE"
elif grep -q "^#gpu_mem=" "$CONFIG_FILE" 2>/dev/null; then
    # Décommenter et mettre à jour
    sed -i "s/^#gpu_mem=.*/gpu_mem=256/" "$CONFIG_FILE"
    ok "gpu_mem activé → 256 Mo dans $CONFIG_FILE"
else
    # Ajouter la ligne
    echo "gpu_mem=256" >> "$CONFIG_FILE"
    ok "gpu_mem=256 ajouté dans $CONFIG_FILE"
fi

CURRENT_GPU=$(vcgencmd get_mem gpu 2>/dev/null | grep -o '[0-9]*' || echo "0")
if [ "$CURRENT_GPU" -lt 256 ] 2>/dev/null; then
    warn "Redémarrage requis pour appliquer gpu_mem=256 (actuellement ${CURRENT_GPU}M)"
    REBOOT_NEEDED=true
else
    ok "Mémoire GPU déjà à ${CURRENT_GPU}M"
fi
fi

systemctl restart weston || true
sleep 8
systemctl is-active --quiet weston \
    && ok "Weston actif" \
    || warn "Weston en erreur : journalctl -u weston -f"
systemctl restart videoplayer || true
sleep 5
systemctl is-active --quiet videoplayer \
    && ok "SmartVision actif" \
    || warn "SmartVision en erreur : journalctl -u videoplayer -f"

IP=$(hostname -I 2>/dev/null | awk '{print $1}' || echo "IP_DU_PI")
echo ""
echo -e "${BOLD}${GREEN}"
echo "  ╔══════════════════════════════════════════════╗"
echo "  ║         ✅  Installation terminée !          ║"
echo "  ╠══════════════════════════════════════════════╣"
printf  "  ║  Interface web : http://%-20s║\n" "${IP}:8080"
printf  "  ║  Répertoire    : %-27s║\n" "${INSTALL_DIR}"
echo "  ╠══════════════════════════════════════════════╣"
echo "  ║  Démarrage auto au boot    : ✅               ║"
echo "  ║  Redémarrage après panne   : ✅               ║"
echo "  ║  Vidéos/DB conservées      : ✅               ║"
echo "  ╠══════════════════════════════════════════════╣"
echo "  ║  Logs :                                      ║"
echo "  ║    journalctl -u videoplayer -f              ║"
echo "  ║    journalctl -u weston -f                   ║"
echo "  ╚══════════════════════════════════════════════╝"
echo -e "  © Lucas BOUVERET — Tous droits réservés${NC}"
echo ""

if [ "$REBOOT_NEEDED" = true ]; then
    echo -e "${BOLD}${YELLOW}"
    echo "  ╔══════════════════════════════════════════════╗"
    echo "  ║  ⚠  Redémarrage requis                       ║"
    echo "  ║  gpu_mem=256 sera actif après reboot          ║"
    echo "  ║                                              ║"
    echo "  ║    sudo reboot                               ║"
    echo "  ╚══════════════════════════════════════════════╝"
    echo -e "${NC}"
fi
